def strategy(history, rng):
    rounds = len(history)

    if rounds == 0:
        return 'C'

    def opp(idx):
        return history[idx][1]

    def me(idx):
        return history[idx][0]

    last_o = opp(rounds - 1)
    last_m = me(rounds - 1)

    # Counts
    opp_c = 0
    opp_d = 0
    for i in range(rounds):
        if opp(i) == 'C':
            opp_c += 1
        else:
            opp_d += 1

    # Early-game adaptive probe / cooperation building
    if rounds < 12:
        # If opponent opened with D, don't be a permanent sucker.
        if opp_d == 0:
            return 'C'
        if opp_c == 0:
            # always been defected on; punish lightly but test once
            if rounds % 4 == 0:
                return 'C'
            return 'D'
        # mixed start: reciprocate last
        return last_o

    # Defection ratio tracking
    ratio_d = opp_d / float(rounds)

    # Identify run lengths for exploitation and retaliation
    run_o = 1
    i = rounds - 1
    while i > 0 and opp(i - 1) == last_o:
        run_o += 1
        i -= 1

    run_m = 1
    j = rounds - 1
    while j > 0 and me(j - 1) == last_m:
        run_m += 1
        j -= 1

    # Cooperative but not naive: play TFT-like with forgiveness and endgame shift.
    if last_o == 'C':
        # Opponent cooperated; mostly cooperate, occasional opportunistic D
        # against highly cooperative opponents in mid-game.
        if ratio_d < 0.15 and rounds < 85 and rounds > 25:
            # small chance to exploit very cooperative opponent
            if rng.random() < 0.04:
                return 'D'
        return 'C'

    # Opponent defected
    # If they are mostly cooperative, forgive quickly (noise resilience)
    if ratio_d < 0.12:
        # forgive after single defection, but if repeated punish
        if run_o >= 2:
            return 'D'
        return 'C'

    # Moderately exploitative opponent
    if ratio_d < 0.35:
        # retaliate, but sometimes forgive to avoid endless DD
        if run_o >= 3:
            # long defection streak: stay D a bit, then probe C
            if run_m >= 3:
                return 'C'
            return 'D'
        if run_o == 2:
            return 'D'
        # single defection
        return 'D' if rng.random() < 0.7 else 'C'

    # Highly defective opponent: play D mostly, but probe occasionally
    if ratio_d < 0.7:
        if rounds > 80:
            # endgame: exploit defectors harder
            return 'D'
        if run_o >= 4:
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Nearly always defecting opponent: defect back, rare probe
    if rounds > 90:
        return 'D'
    if rng.random() < 0.05:
        return 'C'
    return 'D'

